@-moz-document domain("creator.nightcafe.studio") {
/* NightCafe Hacker Green Glass v4.0.5 | Userstyles.org LEGACY Mozilla CSS | no UserCSS, no preprocessors */

/* 01: NightCafe dark terminal foundation */

html,body{background:#010901!important;color:#b6ffc5!important;font-family:Consolas,"Lucida Console","Courier New",monospace!important;color-scheme:dark!important;}

/* Grid is painted on the root canvas, behind page content and glass panels. */
html {
  min-height:100%!important;
  background-color:#0a0a0a!important;
  background-image:linear-gradient(rgba(100,255,155,.15) 1px,transparent 1px),linear-gradient(90deg,rgba(100,255,155,.15) 1px,transparent 1px),repeating-linear-gradient(0deg,rgba(100,255,155,.035) 0px,rgba(100,255,155,.035) 1px,transparent 1px,transparent 4px)!important;
  background-size:40px 40px,40px 40px,100% 4px!important;
  background-position:0 0,0 0,0 0!important;
  background-repeat:repeat!important;
  background-attachment:fixed!important;
}

/* Clear only page shells; preserve cards, dialogs, menus and media. */
html body,
html body #__next,
html body #root,
html body #app,
html body main,
html body [role="main"] {
  background-color:transparent!important;
  background-image:none!important;
}

#__next,#root,#app{color:#b6ffc5!important;}

body,button,input,textarea,select,option,label,nav,aside,[role="menu"],[role="menuitem"],[role="tab"],[role="button"],[role="combobox"],[role="option"],.MuiTypography-root{font-family:Consolas,"Lucida Console","Courier New",monospace!important;}

h1,h2,h3,h4,h5,h6{color:#bdffca!important;letter-spacing:.3px!important;text-shadow:0 0 8px rgba(0,255,102,.24)!important;}

a,[role="link"]{color:#adf8bd!important;text-decoration-color:rgba(0,255,102,.35)!important;transition:color .18s ease,text-shadow .18s ease!important;}

a:hover,[role="link"]:hover{color:#00ff66!important;text-shadow:0 0 7px rgba(0,255,102,.40)!important;}

::selection{background:#00ff66!important;color:#001908!important;}

button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,[role="tab"]:focus-visible{outline:2px solid #00ff66!important;outline-offset:2px!important;}

/* 02: Header, logo and green navigation */

header,[role="banner"],.MuiAppBar-root{background-color:rgba(1,19,8,.92)!important;background-image:linear-gradient(180deg,rgba(5,43,18,.91),rgba(1,17,8,.93))!important;border-bottom:1px solid rgba(0,255,102,.52)!important;box-shadow:0 3px 14px rgba(0,255,102,.12)!important;color:#b6ffc5!important;}

header a,header nav a,[role="banner"] a,header button,header [role="button"]{color:#b6ffc5!important;text-shadow:0 0 4px rgba(0,255,102,.16)!important;outline:none!important;}

