header a[href$="/feed"],header a[href="/feed"],header nav a[href$="/feed"]{outline:none!important;box-shadow:none!important;}

header a[href$="/feed"]:focus-visible,header a[href="/feed"]:focus-visible{outline:2px solid #00ff66!important;}

header a[href="/"] img,header a[href="/"] svg,header img[alt*="NightCafe"],header [class*="logo"] img,header [class*="logo"] svg,[role="banner"] [class*="logo"] img{filter:sepia(1) saturate(6) hue-rotate(73deg) brightness(1.45) drop-shadow(0 0 5px rgba(0,255,102,.85)) drop-shadow(0 0 14px rgba(0,255,102,.50))!important;transition:filter .25s ease!important;}

header a[href="/"]:hover img,header a[href="/"]:hover svg,header [class*="logo"] img:hover{filter:sepia(1) saturate(8) hue-rotate(73deg) brightness(1.75) drop-shadow(0 0 9px rgba(0,255,102,.95)) drop-shadow(0 0 21px rgba(0,255,102,.70))!important;}

header a[href*="promptle"],header button[title*="Promptle"],header a[href*="credits"],header [class*="credit"],header [class*="Credit"],header [class*="avatar"]{background-color:rgba(3,45,20,.61)!important;border:1px solid rgba(0,255,102,.45)!important;border-radius:12px!important;box-shadow:0 0 10px rgba(0,255,102,.12)!important;}

